"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7270],{29216:e=>{e.exports=JSON.parse('{"functions":[{"name":"playerFavoritedGame","desc":"Resolves the favourite-the-game prompt and pays out the award.\\n\\nThe claim is recorded whether or not the player actually favourited, so the\\nprompt is only ever shown once \u2014 but coins are only credited when\\n`didFavorite` is true. Both outcomes are logged to analytics so the prompt\'s\\nconversion rate is measurable.","params":[{"name":"player","desc":"the prompted player","lua_type":"Player"},{"name":"didFavorite","desc":"whether they accepted","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":61,"path":"src/Server/Features/Core/MonetizationService.luau"}},{"name":"_startDailyRewards","desc":"Starts the daily login reward loop, gated on `FeatureFlags.DailyRewards`\\n(on by default).\\n\\nInitialises [DailyRewards] with `DailyRewardData`, then handles each\\n`PlayerClaimRequest` from the Claim button: it re-validates the claim\\nserver-side against the player\'s own `lastClaimAt` and `claimedDays` \u2014\\nnever trusting the client\'s assertion that a day is due \u2014 writes the new\\nclaim state, and only then grants. Coin rewards go through\\n[CurrencyService.add]; item rewards are currently inert (see the class\\nnote).","params":[],"returns":[],"function_type":"static","private":true,"source":{"line":120,"path":"src/Server/Features/Core/MonetizationService.luau"}},{"name":"_startWelcomeBadgeAward","desc":"Awards the welcome badges listed in `GameData.welcomeBadges` to everyone who\\ndoes not already hold them, covering both current and future players.\\n\\nReturns immediately unless the running place is `GameData.liveExperienceId`,\\nso test and development places never burn badge awards. Each grant is spaced\\n0.2s apart to stay clear of the badge API\'s rate limit.","params":[],"returns":[],"function_type":"static","private":true,"source":{"line":206,"path":"src/Server/Features/Core/MonetizationService.luau"}},{"name":"start","desc":"Boots the service: starts the daily reward loop and the welcome badge\\nawards. Each applies its own gate, so this is safe to call unconditionally.","params":[],"returns":[],"function_type":"static","source":{"line":239,"path":"src/Server/Features/Core/MonetizationService.luau"}}],"properties":[],"types":[],"name":"MonetizationService","desc":"Engagement rewards that sit alongside the paid monetization path: the daily\\nlogin streak, the welcome badge grants, and the one-off favourite-the-game\\naward.\\n\\nAll three are claim-gated rather than currency-gated, and each records its\\nclaim on the profile so a reward cannot be taken twice.\\n\\n`FeatureFlags.DailyRewards` is **on**; with it off,\\n[MonetizationService._startDailyRewards] returns before initialising the\\nrewards system, so no claim UI is served and no claims are accepted. The\\nwelcome badge path is independently gated on the running place being the\\nlive experience.\\n\\n:::info InventoryService is stubbed\\n`Features.Shop.InventoryService` was not ported here (TODO Layer 12), so the\\nlocal `InventoryService` is nil. Daily rewards of `rewardType == \\"item\\"`\\nstill log their analytics event but silently grant nothing; coin rewards are\\nunaffected.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":28,"path":"src/Server/Features/Core/MonetizationService.luau"}}')}}]);